class Pair<T, S>{
    T node;
    S idx;
    Pair(T node, S idx){
        this.node = node;
        this.idx = idx;
    }

    public S getValue() {
        return idx;
    }

    public T getKey() {
        return node;
    }
}
class Solution {
    public List<Integer> bottomView(TreeNode root) {
        Map<Integer, Integer> map = new TreeMap<>();
        LinkedList<Pair<TreeNode, Integer>> queue = new LinkedList<>();
        queue.add(new Pair<>(root, 0));

        while(!queue.isEmpty()){
            Pair<TreeNode, Integer> curr = queue.poll();
            if(curr.node.left != null) queue.add(new Pair<>(curr.node.left, curr.idx -1));
            if(curr.node.right != null) queue.add(new Pair<>(curr.node.right, curr.idx+1));
            map.put(curr.idx, curr.node.data);
        }
        return new LinkedList<>(map.values());
    }
}
